<template>
  <div class="server-page" v-loading="initialLoading"><div class="server-heading"><div><h2>服务器状态与安全防护</h2><p>自动限速、临时封禁及向所有班干发送安全提醒。每 15 秒刷新。</p></div><el-button :loading="loading" @click="load">立即刷新</el-button></div>
    <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon />
    <template v-if="state"><div class="status-grid"><article><span>最近一分钟请求</span><strong>{{ state.requests_last_minute }}</strong><small>拦截 {{ state.rejected_last_minute }} 次 · 当前处理 {{ state.inflight_requests }} 个</small></article><article><span>应用容器 CPU</span><strong>{{ percent(state.resources.container_cpu_percent) }}</strong><small>配额 {{ state.resources.container_cpu_limit??'未读取' }} 核</small></article><article><span>应用容器内存</span><strong>{{ bytes(state.resources.container_memory_used) }}</strong><small>限制 {{ bytes(state.resources.container_memory_limit) }} · 宿主可用 {{ bytes(state.resources.host_memory_available) }}</small></article><article><span>磁盘剩余</span><strong>{{ bytes(state.resources.disk_free) }}</strong><small>总量 {{ bytes(state.resources.disk_total) }}</small></article><article><span>当前网络发送速率</span><strong>{{ state.resources.network_send_bytes_per_second==null?'待采样':bytes(state.resources.network_send_bytes_per_second)+'/s' }}</strong><small>接收 {{ state.resources.network_receive_bytes_per_second==null?'待采样':bytes(state.resources.network_receive_bytes_per_second)+'/s' }} · 带宽预算 3 Mbps</small></article><article><span>累计拦截 / 运行时间</span><strong>{{ state.rejected_requests }} 次</strong><small>{{ duration(state.uptime_seconds) }} · 计数在服务重启后重新累计</small></article></div>
    <p class="server-note">{{ state.resources.scope }}</p>
    <section class="server-section"><h3>当前临时封禁（{{ state.blocked_sources.length }}）</h3><p class="server-note">先短时限速，连续超限临时封禁来源。校园网络可能共用出口 IP；误封可由另一可访问来源的班干解除，或等待自动到期。</p><div v-for="row in state.blocked_sources" :key="row.peer" class="blocked-row"><code>{{ row.peer }}</code><span>剩余 {{ row.remaining_seconds }} 秒</span><el-button type="warning" plain size="small" @click="unblock(row.peer)">解除封禁</el-button></div><el-empty v-if="!state.blocked_sources.length" description="暂无临时封禁" :image-size="50" /></section>
    <section class="server-section"><h3>最近安全事件</h3><div class="events-scroll"><article v-for="event in state.events" :key="event.id" class="event-row"><div><strong>{{ event.reason }}</strong><el-tag size="small" type="warning">{{ event.action }}</el-tag></div><p>{{ event.time }} · {{ event.peer }} · {{ event.count }} 次</p><code>{{ event.path }}</code></article><el-empty v-if="!state.events.length" description="暂无异常请求事件" :image-size="50" /></div></section>
    <section class="server-section"><h3>班干告警投递</h3><el-alert v-if="state.alert_readiness" :title="`共 ${state.alert_readiness.leaders} 名管理员 / 班干；有效邮箱 ${state.alert_readiness.email_contacts} 人，有效 QQ ${state.alert_readiness.qq_contacts} 人。邮件服务${state.alert_readiness.smtp_configured?'已配置':'未配置'}，QQ 服务${state.alert_readiness.qq_enabled?'已启用':'未启用'}。`" :type="state.alert_readiness.smtp_configured&&state.alert_readiness.qq_enabled&&state.alert_readiness.email_contacts===state.alert_readiness.leaders&&state.alert_readiness.qq_contacts===state.alert_readiness.leaders?'success':'warning'" :closable="false" show-icon /><p class="server-note">首次异常触发后立即加入后台投递；同一冷却期内合并事件。邮件与 QQ 私信分别发送给所有系统管理员、班干的有效联系方式；缺失信息或机器人 / 邮箱配置异常时会在此标明。通道繁忙最多重试 3 次，不无限重发。</p><el-alert v-if="state.pending_alert" title="安全告警正在排队投递或等待通道重试" type="warning" :closable="false" /><article v-for="(alert,index) in state.alerts" :key="index" class="event-row"><strong>{{ alert.event }}</strong><p>{{ alert.time }} · 合并 {{ alert.incidents }} 次</p><p v-for="(channel,name) in alert.channels" :key="name">{{ name==='email'?'邮件':'QQ 私信' }}：{{ channel.state }} · 成功 {{ channel.sent }} / 失败 {{ channel.failed }} / 缺少联系方式 {{ channel.missing }}</p></article><el-empty v-if="!state.alerts.length&&!state.pending_alert" description="暂无告警投递记录" :image-size="50" /></section>
    <section class="server-section"><h3>防护设置</h3><p class="server-note">仅系统管理员可修改。默认阈值为约 50 人及共享校园网络保留余量。关闭自动防护不会关闭已有登录账号和文件并发限制。</p><el-form label-position="top" @submit.prevent="save"><div class="defense-switches"><el-form-item label="启用自动请求防护"><el-switch v-model="form.enabled" :disabled="!state.can_configure" /></el-form-item><el-form-item label="异常时向所有班干发邮件及 QQ 私信"><el-switch v-model="form.alerts_enabled" :disabled="!state.can_configure" /></el-form-item></div><div class="defense-grid"><el-form-item v-for="field in fields" :key="field.key" :label="field.label"><el-input-number v-model="form[field.key]" :min="field.min" :max="field.max" :precision="0" :disabled="!state.can_configure" /></el-form-item></div><el-button v-if="state.can_configure" type="primary" native-type="submit" :loading="saving">保存防护设置</el-button></el-form></section>
    </template>
  </div>
</template>
<script setup>
import {onMounted,onBeforeUnmount,ref,reactive} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import api from '../api'
const state=ref(null),loading=ref(false),initialLoading=ref(true),saving=ref(false),error=ref(''),form=reactive({})
let timer,disposed=false,initialized=false
const fields=[{key:'ip_per_10_seconds',label:'同一来源每 10 秒最多请求',min:150,max:3000},{key:'ip_per_minute',label:'同一来源每分钟最多请求',min:600,max:12000},{key:'global_per_10_seconds',label:'全站每 10 秒最多请求',min:600,max:12000},{key:'login_per_minute',label:'同一来源每分钟登录 / 重置请求',min:60,max:600},{key:'login_failures_per_minute',label:'同一来源每分钟失败登录阈值',min:15,max:300},{key:'block_seconds',label:'临时封禁时长（秒）',min:60,max:1800},{key:'alert_cooldown_seconds',label:'告警合并冷却（秒）',min:60,max:3600}]
function bytes(value){if(value==null)return'未读取';if(value<1024)return`${value} B`;for(const [unit,size]of[['GiB',1024**3],['MiB',1024**2],['KiB',1024]])if(value>=size)return`${(value/size).toFixed(1)} ${unit}`;return'0 B'}
function percent(value){return value==null?'待采样':`${value.toFixed(1)}%`}
function duration(seconds){return`${Math.floor(seconds/3600)} 小时 ${Math.floor(seconds%3600/60)} 分钟`}
async function load(){if(loading.value||disposed)return;loading.value=true;try{const {data}=await api.get('/api/server/status');if(disposed)return;state.value=data;if(!initialized){Object.assign(form,data.settings);initialized=true}error.value=''}catch(err){if(!disposed)error.value=err.response?.data?.detail||'无法获取服务器状态'}finally{loading.value=false;initialLoading.value=false}}
async function save(){if(saving.value)return;saving.value=true;try{Object.assign(form,(await api.put('/api/server/defense-settings',{...form})).data);ElMessage.success('防护设置已保存');await load()}catch(err){ElMessage.error(err.response?.data?.detail||'保存失败')}finally{saving.value=false}}
async function unblock(peer){try{await ElMessageBox.confirm(`解除 ${peer} 的临时封禁？后续异常仍会重新触发防护。`,'确认解除');await api.post('/api/server/unblock',{peer});ElMessage.success('已解除临时封禁');await load()}catch(err){if(err!=='cancel'&&err!=='close')ElMessage.error(err.response?.data?.detail||'解除失败')}}
onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden)load()},15000)})
onBeforeUnmount(()=>{disposed=true;clearInterval(timer)})
</script>
<style scoped>
.server-page{max-width:1200px;margin:auto;min-width:0}.server-heading{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:20px}h2{margin:0 0 10px}h3{margin:0 0 16px}.server-heading p,.server-note{font-size:13px;line-height:1.8;color:var(--el-text-color-secondary)}.status-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.status-grid article,.server-section{background:var(--el-bg-color);border:1px solid var(--el-border-color-lighter);border-radius:14px;padding:20px;min-width:0}.status-grid article{display:flex;flex-direction:column;gap:12px}.status-grid span,.status-grid small{font-size:12px;line-height:1.8;color:var(--el-text-color-secondary)}.status-grid strong{font-size:25px;overflow-wrap:anywhere}.server-section{margin-top:20px}.blocked-row,.event-row>div{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap}.blocked-row{padding:14px 0;border-bottom:1px solid var(--el-border-color-lighter)}.events-scroll{max-height:450px;overflow:auto}.event-row{padding:16px 0;border-bottom:1px solid var(--el-border-color-lighter);overflow-wrap:anywhere;font-size:13px}.event-row p{color:var(--el-text-color-secondary);line-height:1.8}.defense-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 20px}.defense-grid :deep(.el-input-number){width:100%}.defense-switches{display:flex;gap:24px;flex-wrap:wrap}code{overflow-wrap:anywhere}@media(max-width:1000px){.status-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){h2{font-size:22px}.status-grid{gap:10px}.status-grid article{padding:14px}.status-grid strong{font-size:21px}.server-section{padding:18px 14px}.defense-grid{grid-template-columns:minmax(0,1fr)}}
</style>
